<template><div class="config-page page-container"><header class="page-heading"><div><span class="eyebrow">SECURITY AUDIT / GOVERNANCE</span><h1>审计中心及安全管理后台</h1><p>配置日志保留、敏感字段脱敏、自动备份、登录风控、IP 白名单和操作拦截策略。</p></div><el-button @click="router.push('/security-audit')">返回安全审计中心</el-button></header><el-card shadow="never"><el-form :model="form" label-position="top"><el-row :gutter="16"><el-col :span="12"><el-form-item label="操作日志保留天数"><el-input-number v-model="form.logRetentionDays" :min="30" :max="3650"/></el-form-item><el-form-item label="敏感字段自动脱敏"><el-switch v-model="form.maskingEnabled" active-text="启用" inactive-text="停用"/></el-form-item><el-form-item label="敏感操作双人审批"><el-switch v-model="form.dualApproval" active-text="启用" inactive-text="停用"/></el-form-item></el-col><el-col :span="12"><el-form-item label="自动备份周期"><el-select v-model="form.backupCycle" style="width:100%"><el-option label="每日" value="DAILY"/><el-option label="每周" value="WEEKLY"/><el-option label="每月" value="MONTHLY"/></el-select></el-form-item><el-form-item label="登录风控"><el-checkbox-group v-model="form.riskRules"><el-checkbox label="IP">IP 异常</el-checkbox><el-checkbox label="FAIL">连续登录失败</el-checkbox><el-checkbox label="DEVICE">新设备登录</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="IP 白名单"><el-input v-model="form.ipWhitelist" placeholder="多个 IP 用逗号分隔"/></el-form-item></el-col></el-row></el-form></el-card><div class="actions"><el-button @click="restore">恢复默认</el-button><el-button type="primary" @click="save">保存配置</el-button></div></div></template>
<script setup>import {reactive,onMounted} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import request from '../utils/request';const router=useRouter();const defaults={logRetentionDays:365,maskingEnabled:true,dualApproval:false,backupCycle:'DAILY',riskRules:['IP','FAIL'],ipWhitelist:''};const form=reactive({...defaults,...(JSON.parse(localStorage.getItem('river-security-config')||'null')||{})});const save=async()=>{try{await request.put('/v1/system-config/security',JSON.stringify(form),{headers:{'Content-Type':'application/json'}});localStorage.setItem('river-security-config',JSON.stringify(form));ElMessage.success('安全配置已保存')}catch(e){ElMessage.error(e.message||'配置保存失败')}};const restore=()=>{Object.assign(form,defaults);ElMessage.info('已恢复默认配置，请保存后生效')};onMounted(async()=>{try{const saved=await request.get('/v1/system-config/security');if(saved?.configJson)Object.assign(form,JSON.parse(saved.configJson))}catch(e){ElMessage.warning(e.message||'安全配置加载失败，使用默认配置')}})</script>
<style scoped>.page-heading,.actions{display:flex;align-items:center;justify-content:space-between;gap:16px}.page-heading{margin-bottom:18px}.page-heading h1{margin:6px 0;font-size:26px}.page-heading p{margin:0;color:#86909c;font-size:13px}.eyebrow{color:#165dff;font-size:12px;font-weight:700;letter-spacing:.08em}.actions{justify-content:flex-end;margin-top:18px}</style>
